# Get sorted list of generations from first run
generations = sorted(runs[0].keys())

filename = "C:/Users/rensk/Documents/Amsterdam/revolve2/stats/morph_065-1/birth_deaths.json."
with open(filename, "r") as f:
    birth_deaths = json.load(f)
    
all_births = {}
all_deaths = {}

for exp_data in birth_deaths.values():
    for gen_str, num_births in exp_data["births"].items():
        gen = int(gen_str)
        all_births.setdefault(gen, []).append(num_births)
    for gen_str, num_deaths in exp_data["deaths"].items():
        gen = int(gen_str)
        all_deaths.setdefault(gen, []).append(num_deaths)

# Compute averages
avg_births = {gen: np.mean(vals) for gen, vals in all_births.items()}
avg_births[0] = 0
avg_deaths = {gen: np.mean(vals) for gen, vals in all_deaths.items()}
avg_deaths[99] = 0


# Plot each run in light gray
plt.figure(figsize=(10, 6))

for run_data in runs:
    sizes = [run_data[gen] for gen in generations]
    plt.plot(generations, sizes, color="lightgray", linewidth=1)

# Compute mean and std dev
all_sizes = np.array([[run[gen] for gen in generations] for run in runs])
avg_sizes = np.mean(all_sizes, axis=0)
std_sizes = np.std(all_sizes, axis=0)

# Plot average
plt.plot(generations, avg_sizes, color="blue", linewidth=2.5, label="Population size")
plt.plot(generations, [avg_births[g] for g in generations], label="Avg Births", color="green")
plt.plot(generations, [avg_deaths[g] for g in generations], label="Avg Deaths", color="red")# Add shaded standard deviation band
plt.fill_between(
    generations,
    avg_sizes - std_sizes,
    avg_sizes + std_sizes,
    color="blue",
    alpha=0.2,
    label="± Std Dev"
)

# Labels & style
plt.xlabel("Generation")
plt.ylabel("Population Size")
plt.title("Population Size Per Generation, 0.65-1.0")
plt.legend()
plt.grid(True)
plt.show()
